const listAliveSessionsByUser = `-- name: ListAliveSessionsByUser :many
SELECT id, user_id, refresh_token_hash, device_label, ip_hash, user_agent, created_at, last_seen_at, expires_at, revoked_at FROM session
WHERE user_id = $1
  AND revoked_at IS NULL
  AND expires_at > $2
  AND (
    $4::timestamptz IS NULL
    OR (created_at, id) > ($4::timestamptz, $5::uuid)
  )
ORDER BY created_at ASC, id ASC
LIMIT $3
`

type ListAliveSessionsByUserParams struct {
	UserID        uuid.UUID
	ExpiresAt     pgtype.Timestamptz
	Limit         int32
	CursorCreated pgtype.Timestamptz
	CursorID      *uuid.UUID
}

func (q *Queries) ListAliveSessionsByUser(ctx context.Context, arg ListAliveSessionsByUserParams) ([]Session, error) {
	rows, err := q.db.Query(ctx, listAliveSessionsByUser,
		arg.UserID,
		arg.ExpiresAt,
		arg.Limit,
		arg.CursorCreated,
		arg.CursorID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Session
	for rows.Next() {
		var i Session
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.RefreshTokenHash,
			&i.DeviceLabel,
			&i.IpHash,
			&i.UserAgent,
			&i.CreatedAt,
			&i.LastSeenAt,
			&i.ExpiresAt,
			&i.RevokedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

