const upsertThrottleFailure = `-- name: UpsertThrottleFailure :one
INSERT INTO auth_throttle (subject_hash, failed_count, locked_until, last_failed_at)
VALUES ($1, $2, $3, $4)
ON CONFLICT (subject_hash) DO UPDATE
SET
  failed_count = EXCLUDED.failed_count,
  locked_until = EXCLUDED.locked_until,
  last_failed_at = EXCLUDED.last_failed_at
RETURNING subject_hash, failed_count, locked_until, last_failed_at
`

